/**
 * Kumpulan kosakata HSK.
 *
 * HSK 1: daftar lengkap 150 kata resmi (standar HSK 2.0 / International
 * Curriculum for Chinese Language Education, Hanban).
 * Referensi: daftar kosakata resmi HSK 1.
 *
 * HSK 2: kata BARU HSK 2 (diluar HSK 1), total ±150 kata mengikuti daftar
 * resmi HSK 2.0. Setiap level hanya memuat kata yang tidak ada di level
 * sebelumnya (progress/leveling berbasis kata per level).
 *
 * HSK 3: kata BARU HSK 3 (diluar HSK 1 & 2), mengikuti daftar resmi HSK 2.0
 * (300 kata; 298 hanzi unik). Kata yang sudah ada di level bawah otomatis
 * dibuang (aturan "satu kata = satu level") → tersimpan 287 kata. Direview
 * terhadap daftar resmi (v0.2.0): kata non-resmi (kebanyakan HSK 4) dibuang.
 *
 * HSK 4: kata BARU HSK 4 (600 kata resmi; 2 kata sudah ada di HSK 2: 得 & 等)
 * → tersimpan 598 kata (v0.3.0).
 *
 * HSK 5: kata BARU HSK 5 (mengikuti daftar resmi HSK 2.0 dari XLS chinesetest.cn);
 * dedup terhadap HSK 1–4 (satu kata = satu level) → tersimpan 1300 kata (v0.5.0).
 * Seluruh arti ditulis ulang dalam Bahasa Indonesia.
 *
 * HSK 6: kata BARU HSK 6 (mengikuti daftar resmi HSK 2.0 dari XLS chinesetest.cn);
 * dedup terhadap HSK 1–5 (satu kata = satu level) → tersimpan 2499 kata (v0.5.0).
 */
